contracts/AchievementManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./PlayerProfile.sol";
import "./BadgeNFT.sol";

contract AchievementManager is Ownable {

    PlayerProfile public playerProfile;
    BadgeNFT      public badgeNFT;
    address       public quizContract;

    struct Achievement {
        string  name;
        string  description;
        uint8   flagIndex;       // PlayerProfile bit pozisyonu
        uint256 badgeTokenId;    // BadgeNFT token ID (3'ten başlar)
        // Kriter türü ve eşiği
        CriteriaType criteriaType;
        uint256 criteriaValue;
    }

    enum CriteriaType {
        TOTAL_SCORE,    // toplam skor eşiği
        STREAK_DAYS,    // streak gün eşiği
        GAMES_PLAYED,   // toplam oyun sayısı
        PERFECT_SCORE   // 10/10 alan oyun sayısı
    }

    Achievement[] public achievements;

    // Oyuncu istatistikleri (quiz contract günceller)
    mapping(address => uint256) public gamesPlayed;
    mapping(address => uint256) public perfectGames;

    event AchievementAdded(uint8 flagIndex, string name);
    event AchievementUnlocked(address indexed player, uint8 flagIndex, string name);

    modifier onlyQuiz() {
        require(msg.sender == quizContract, "Only quiz contract");
        _;
    }

    constructor(address _playerProfile, address _badgeNFT) Ownable() {
        playerProfile = PlayerProfile(_playerProfile);
        badgeNFT      = BadgeNFT(_badgeNFT);
        _initAchievements();
    }

    function setQuizContract(address _quiz) external onlyOwner {
        quizContract = _quiz;
    }

    // Başlangıç achievement'ları
    function _initAchievements() internal {
    _addAchievement("First Step",       "Complete your first quiz",    0, 3,  CriteriaType.GAMES_PLAYED,  1);
    _addAchievement("Week Warrior",     "7 day streak",                1, 4,  CriteriaType.STREAK_DAYS,   7);
    _addAchievement("Month Master",     "30 day streak",               2, 5,  CriteriaType.STREAK_DAYS,   30);
    _addAchievement("Knowledge Seeker", "Earn 100 total score",        3, 6,  CriteriaType.TOTAL_SCORE,   100);
    _addAchievement("Expert",           "Earn 1000 total score",       4, 7,  CriteriaType.TOTAL_SCORE,   1000);
    _addAchievement("Perfectionist",    "First perfect score (10/10)", 5, 8,  CriteriaType.PERFECT_SCORE, 1);
    _addAchievement("Flawless",         "5 perfect scores",            6, 9,  CriteriaType.PERFECT_SCORE, 5);
    _addAchievement("Veteran",          "Complete 50 quizzes",         7, 10, CriteriaType.GAMES_PLAYED,  50);
}
    function _addAchievement(
        string memory name,
        string memory desc,
        uint8 flagIndex,
        uint256 tokenId,
        CriteriaType cType,
        uint256 cValue
    ) internal {
        achievements.push(Achievement(name, desc, flagIndex, tokenId, cType, cValue));
        emit AchievementAdded(flagIndex, name);
    }

    // Quiz contract her oyun sonunda çağırır
    function checkAchievements(address player, uint8 score) external onlyQuiz {
        gamesPlayed[player]++;
        if (score == 10) perfectGames[player]++;

        (uint256 totalScore,,,,uint256 streakDays,,uint32 currentFlags) =
            playerProfile.getProfile(player);

        for (uint256 i = 0; i < achievements.length; i++) {
            Achievement storage ach = achievements[i];

            // Zaten unlock edildi mi?
            if ((currentFlags & uint32(1 << ach.flagIndex)) != 0) continue;

            bool unlocked = false;

            if (ach.criteriaType == CriteriaType.TOTAL_SCORE) {
                unlocked = totalScore >= ach.criteriaValue;
            } else if (ach.criteriaType == CriteriaType.STREAK_DAYS) {
                unlocked = streakDays >= ach.criteriaValue;
            } else if (ach.criteriaType == CriteriaType.GAMES_PLAYED) {
                unlocked = gamesPlayed[player] >= ach.criteriaValue;
            } else if (ach.criteriaType == CriteriaType.PERFECT_SCORE) {
                unlocked = perfectGames[player] >= ach.criteriaValue;
            }

            if (unlocked) {
                playerProfile.setAchievementFlag(player, ach.flagIndex);
                emit AchievementUnlocked(player, ach.flagIndex, ach.name);
            }
        }
    }

    // Kullanıcı unlock ettiği achievement'ın NFT'sini mint eder
    function mintAchievementBadge(uint8 achievementIndex) external {
        require(achievementIndex < achievements.length, "Invalid index");
        Achievement storage ach = achievements[achievementIndex];

        require(
            playerProfile.hasAchievement(msg.sender, ach.flagIndex),
            "Achievement not unlocked"
        );
        require(
            !badgeNFT.minted(msg.sender, ach.badgeTokenId),
            "Already minted"
        );

        badgeNFT.mint(msg.sender, ach.badgeTokenId);
    }

    // Tüm achievement'ları döndür (frontend için)
    function getAllAchievements() external view returns (Achievement[] memory) {
        return achievements;
    }

    // Oyuncunun achievement durumunu döndür
    function getPlayerAchievements(address player) external view returns (
        bool[] memory unlocked,
        bool[] memory minted_
    ) {
        unlocked = new bool[](achievements.length);
        minted_  = new bool[](achievements.length);

        for (uint256 i = 0; i < achievements.length; i++) {
            unlocked[i] = playerProfile.hasAchievement(player, achievements[i].flagIndex);
            minted_[i]  = badgeNFT.minted(player, achievements[i].badgeTokenId);
        }
    }

    // Owner yeni achievement ekleyebilir
    function addAchievement(
        string memory name,
        string memory desc,
        uint8 flagIndex,
        uint256 tokenId,
        CriteriaType cType,
        uint256 cValue
    ) external onlyOwner {
        _addAchievement(name, desc, flagIndex, tokenId, cType, cValue);
    }
}

contracts/BadgeNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract BadgeNFT is ERC1155, Ownable {

    // Token ID sabitleri
    uint256 public constant WEEKLY_TOP10   = 0;
    uint256 public constant MONTHLY_TOP10  = 1;
    uint256 public constant SEASON_CHAMP   = 2;
    // 3+ → Achievement badge'leri

    // Yetkili mint edebilen adresler (AchievementManager, RewardPool)
    mapping(address => bool) public authorized;

    // Her adres her token'dan kaç tane mint etti (tekrar mint engeli)
    mapping(address => mapping(uint256 => bool)) public minted;

    string private _baseURI;

    event AuthorizedSet(address indexed account, bool status);
    event BadgeMinted(address indexed to, uint256 tokenId);

    constructor(string memory baseURI_) ERC1155(baseURI_) Ownable() {
        _baseURI = baseURI_;
    }

    modifier onlyAuthorized() {
        require(authorized[msg.sender] || msg.sender == owner(), "Not authorized");
        _;
    }

    function setAuthorized(address account, bool status) external onlyOwner {
        authorized[account] = status;
        emit AuthorizedSet(account, status);
    }

    function mint(address to, uint256 tokenId) external onlyAuthorized {
        require(!minted[to][tokenId], "Already minted");
        minted[to][tokenId] = true;
        _mint(to, tokenId, 1, "");
        emit BadgeMinted(to, tokenId);
    }

    function uri(uint256 tokenId) public view override returns (string memory) {
        return string(abi.encodePacked(_baseURI, "/", _toString(tokenId), ".json"));
    }

    function setBaseURI(string memory newURI) external onlyOwner {
        _baseURI = newURI;
        _setURI(newURI);
    }

    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) return "0";
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) { digits++; temp /= 10; }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits--;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }
}

contracts/DailyQuiz.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./PlayerProfile.sol";
import "./RewardPool.sol";
import "./AchievementManager.sol";

contract DailyQuiz is Ownable {

    IERC20           public usdc;
    PlayerProfile    public playerProfile;
    RewardPool       public rewardPool;
    AchievementManager public achievementManager;

    uint256 public entryFee = 10 * 10**6; // 10 USDC (6 decimal)
    uint256 public constant QUESTIONS_PER_DAY = 10;

    // Günlük merkle root: dayIndex → root
    mapping(uint256 => bytes32) public dailyMerkleRoot;

    // Oyuncu günlük durumu
    mapping(address => uint256) public lastPlayedDay;
    mapping(address => mapping(uint256 => bool)) public hasSubmitted;
    mapping(address => mapping(uint256 => uint8)) public dailyScore;

    // Toplam oyun sayısı (leaderboard için)
    uint256 public totalGamesPlayed;

    event QuizEntered(address indexed player, uint256 dayIndex, uint256 fee);
    event QuizCompleted(address indexed player, uint256 dayIndex, uint8 score, uint256 boostedScore);
    event MerkleRootSet(uint256 dayIndex, bytes32 root);
    event EntryFeeUpdated(uint256 newFee);

    constructor(
        address _usdc,
        address _playerProfile,
        address _rewardPool,
        address _achievementManager
    ) Ownable() {
        usdc               = IERC20(_usdc);
        playerProfile      = PlayerProfile(_playerProfile);
        rewardPool         = RewardPool(_rewardPool);
        achievementManager = AchievementManager(_achievementManager);
    }

    // Günün index'i (her gün 00:00 UTC'de artar)
    function todayIndex() public view returns (uint256) {
        return block.timestamp / 1 days;
    }

    // RPi5 her sabah 00:00 UTC'de bu fonksiyonu çağırır
    function setDailyMerkleRoot(bytes32 root, uint256 dayIndex) external onlyOwner {
        require(dailyMerkleRoot[dayIndex] == bytes32(0), "Root already set");
        dailyMerkleRoot[dayIndex] = root;
        emit MerkleRootSet(dayIndex, root);
    }

    // Adım 1: Quiz'e giriş (10 USDC öde)
    function enterQuiz() external {
        uint256 today = todayIndex();

        require(dailyMerkleRoot[today] != bytes32(0), "Quiz not initialized yet");
        require(lastPlayedDay[msg.sender] < today, "Already entered today");

        // USDC transfer (kullanıcı önceden approve etmeli)
        require(
            usdc.transferFrom(msg.sender, address(rewardPool), entryFee),
            "USDC transfer failed"
        );

        // RewardPool'a fee bildir
        rewardPool.receiveFee(entryFee);

        lastPlayedDay[msg.sender] = today;

        emit QuizEntered(msg.sender, today, entryFee);
    }

    // Adım 2: Cevapları gönder
    // answers: her soru için seçilen şık (keccak256 hash'i)
    // proofs: her cevap için RPi5'ten alınan merkle proof
    function submitAnswers(
        bytes32[] calldata answerHashes,
        bytes32[][] calldata proofs
    ) external {
        uint256 today = todayIndex();

        require(lastPlayedDay[msg.sender] == today, "Not entered today");
        require(!hasSubmitted[msg.sender][today], "Already submitted");
        require(answerHashes.length == QUESTIONS_PER_DAY, "Wrong answer count");
        require(proofs.length == QUESTIONS_PER_DAY, "Wrong proof count");

        bytes32 root = dailyMerkleRoot[today];
        uint8 score = 0;

        for (uint256 i = 0; i < QUESTIONS_PER_DAY; i++) {
            // Merkle proof doğrula
            bool valid = MerkleProof.verify(proofs[i], root, answerHashes[i]);
            if (valid) score++;
        }

        hasSubmitted[msg.sender][today] = true;
        dailyScore[msg.sender][today]   = score;
        totalGamesPlayed++;

        // PlayerProfile güncelle (skor + streak + boost)
        playerProfile.recordPlay(msg.sender, score);

        // Achievement kontrol et
        achievementManager.checkAchievements(msg.sender, score);

        // Boosted skoru event'te emit et
        (uint256 totalScore,,,,, uint256 boost,) = playerProfile.getProfile(msg.sender);
        uint256 boosted = (score * boost) / 100;

        emit QuizCompleted(msg.sender, today, score, boosted);
    }

    // Entry fee güncelle (owner)
    function setEntryFee(uint256 newFee) external onlyOwner {
        entryFee = newFee;
        emit EntryFeeUpdated(newFee);
    }

    // Bugünkü quiz hazır mı?
    function isTodayReady() external view returns (bool) {
        return dailyMerkleRoot[todayIndex()] != bytes32(0);
    }

    // Oyuncunun bugün oynayıp oynamadığı
    function canPlay(address player) external view returns (bool) {
        return lastPlayedDay[player] < todayIndex();
    }

    // Oyuncunun bugünkü skoru (oynadıysa)
    function getTodayScore(address player) external view returns (uint8, bool) {
        uint256 today = todayIndex();
        return (dailyScore[player][today], hasSubmitted[player][today]);
    }
}

